import csv, io
rows = csv.DictReader(io.StringIO(inputs["csv"]))
totals = {}
for row in rows:
    totals[row["team"]] = totals.get(row["team"], 0) + int(row["score"])
result = dict(sorted(totals.items()))

import tomllib
config = tomllib.loads(inputs["toml"])
result = {"name": config["project"]["name"], "workers": config["runtime"]["workers"], "enabled": config["runtime"]["enabled"]}

import yaml
config = yaml.safe_load(inputs["yaml"])
result = {"services": sorted(config["services"]), "retries": config["defaults"]["retries"]}

import re
pattern = re.compile(r"level=(?P<level>\w+) request=(?P<request>\w+)")
counts = {}
failed = []
for match in pattern.finditer(inputs["log"]):
    level = match.group("level")
    counts[level] = counts.get(level, 0) + 1
    if level == "error": failed.append(match.group("request"))
result = {"counts": dict(sorted(counts.items())), "failed": failed}

from datetime import datetime, timezone
hours = [datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc).hour for value in inputs["timestamps"]]
result = {str(hour): hours.count(hour) for hour in sorted(set(hours))}

import base64, hashlib
raw = inputs["text"].encode()
result = {"sha256": hashlib.sha256(raw).hexdigest(), "base64": base64.b64encode(raw).decode()}

from html.parser import HTMLParser
class Links(HTMLParser):
    def __init__(self): super().__init__(); self.links=[]
    def handle_starttag(self, tag, attrs):
        if tag == "a":
            href = dict(attrs).get("href")
            if href: self.links.append(href)
parser = Links(); parser.feed(inputs["html"])
result = parser.links

import numpy as np
values = np.array(inputs["values"], dtype=np.int64)
result = {"sum": int(values.sum()), "mean": float(values.mean()), "above": values[values > values.mean()].tolist()}

import re
symbols = []
for path, text in inputs["files"].items():
    for kind, name in re.findall(r"^(class|def)\s+(\w+)", text, re.MULTILINE):
        symbols.append({"kind": kind, "name": name, "path": path})
result = sorted(symbols, key=lambda item: (item["name"], item["path"]))

first = flags.get(name=inputs["name"])
second = flags.get(name=inputs["name"])
result = {"stable": first == second, "value": first}

try:
    upstream.fetch(key=inputs["key"])
    result = {"caught": False}
except Exception as exc:
    result = {"caught": "rate limit" in str(exc).lower()}

items = catalog.search(query=inputs["query"])
details = [catalog.details(item_id=item["id"]) for item in items]
result = {"count": len(details), "markdown": "\n".join(f"- {item['name']}: {item['status']}" for item in details)}
